    size: {sm: "px-3 py-1 text-sm", lg: "px-4 py-2 text-base"}
  },
  defaultVariants: {tone: "primary", size: "sm"}
});
export default function ActionButton({tone,size,className,...props}) {
  return <button {...props} className={classes({tone: tone === undefined ? undefined : tone === "primary" ? "primary" : "secondary", size: size === undefined ? undefined : size === "sm" ? "sm" : "lg", className})}/>;
}

